func newAppContextWithBudget(opts *rootOptions, enabled bool) (*appContext, error) {
	var provider func() (*accountbudgetruntime.Factory, error)
	if enabled && opts.budgetOwner != nil {
		provider = func() (*accountbudgetruntime.Factory, error) {
			if opts.budgetContext == nil {
				return nil, accountbudget.ErrUnavailable
			}
			return opts.budgetOwner.get(opts.budgetContext)
		}
	}
	built, err := tossapp.New(tossapp.Options{
		BudgetProvider: provider,
		OutputFormat:   opts.outputFormat,
		ConfigDir:      opts.configDir,
		SessionFile:    opts.sessionFile,
		Backend:        opts.backend,
	})
	if err != nil {
		return nil, err
	}
	return &appContext{
		format:         built.Format,
		paths:          built.Paths,
		config:         built.Config,
		configService:  built.ConfigService,
		loginConfig:    built.LoginConfig,
		authService:    built.AuthService,
		client:         built.Client,
		session:        built.Session,
		tokenFile:      built.TokenFile,
		lineageService: built.LineageService,
		tradingService: built.TradingService,
	}, nil
}

cmd/tossctl/root_budget.go|rootBudgetOwn:
func (o *rootBudgetOwner) get(ctx context.Context) (*accountbudgetruntime.Factory, error) {
	if o == nil {
		return nil, accountbudget.ErrUnavailable
	}
	select {
	case <-ctx.Done():
		return nil, ctx.Err()
	case <-o.gate:
	}
	defer func() { o.gate <- struct{}{} }()
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if o.closing {
		return nil, accountbudget.ErrUnavailable
	}
	if o.configErr != nil {
		return nil, o.configErr
	}
	if o.factory != nil {
		return o.factory, nil
	}
	f, e := accountbudgetruntime.Open(ctx, o.cfg)
	if e != nil {
		return nil, e
	}
	if f == nil {
		return nil, accountbudget.ErrUnavailable
	}
	o.factory = f
	return f, nil
}

