func newVerifyReconcileReaderForRoot(ctx context.Context, root *rootOptions, creds official.Credentials, tokenFile string, opts ...official.Option) (verifylive.ReconcileReader, verifylive.ReconcileAccount, error) {
	client, err := newRootOfficialClient(ctx, root, creds, tokenFile, opts...)
	if err != nil {
		return nil, verifylive.ReconcileAccount{}, err
	}
	accounts, err := client.Accounts(ctx)
	if err != nil {
		return nil, verifylive.ReconcileAccount{}, reconcileRefusal(verifylive.RefuseAccountsRead,
			"the account list could not be read: "+err.Error())
	}

	for _, a := range accounts {
		if strings.TrimSpace(a.DisplayName) == "" {
			return nil, verifylive.ReconcileAccount{}, reconcileRefusal(verifylive.RefuseAccountMalformedRow,
				"the account list holds a row without an account number")
		}
	}
	if len(accounts) != 1 {
		return nil, verifylive.ReconcileAccount{}, reconcileRefusal(verifylive.RefuseAccountCount,
			fmt.Sprintf("the credentials list %d accounts — reconciliation needs exactly one (Q5)", len(accounts)))
	}
	seq, err := strconv.Atoi(strings.TrimSpace(accounts[0].ID))
	if err != nil || seq <= 0 {
		return nil, verifylive.ReconcileAccount{}, reconcileRefusal(verifylive.RefuseAccountSeqZero,
			"the account's sequence is not a positive number — the request header cannot be pinned")
	}
	bound, err := newRootOfficialClient(ctx, root, creds, tokenFile, append(append([]official.Option(nil), opts...), official.WithAccountSeq(seq))...)
	if err != nil {
		return nil, verifylive.ReconcileAccount{}, err
	}
	ref := strings.TrimSpace(accounts[0].DisplayName)
	return &reconcileReads{client: bound, ref: ref, seq: seq},
		verifylive.ReconcileAccount{Ref: ref, Seq: seq, Count: len(accounts)}, nil
}

internal/accountbudget/engine_poll_linux:
func (b *Budget) EnginePollKey(accountRef, kind string) (ObservationKey, error) {
	if b == nil || accountRef == "" || kind == "" {
		return ObservationKey{}, ErrUnavailable
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed || b.observation == nil {
		return ObservationKey{}, ErrUnavailable
	}
	h := sha256.New()
	for _, field := range []string{"tossos/a166/engine-poll/v1", b.scope, b.instance, accountRef, "engine-poll", kind} {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(field)))
		_, _ = h.Write(size[:])
		_, _ = h.Write([]byte(field))
	}
	var key ObservationKey
	copy(key[:], h.Sum(nil))
	return key, nil
}

func (b *Budget) PollRemaining(ctx context.Context, key ObservationKey) (time.Duration, error) {
	if b == nil || ctx == nil {
		return 0, ErrUnavailable
	}
	b.mu.Lock()
	store := b.observation
	closed := b.closed
	b.mu.Unlock()
	if closed || store == nil {
		return 0, ErrUnavailable
	}
	return store.PollRemaining(ctx, key)
}

