internal/accountbudget/transport_linux.g:
func (t *Transport) RoundTrip(req *http.Request) (resp *http.Response, err error) {
	sent := false
	defer func() {
		if err != nil && !sent {
			err = errors.Join(ErrNotSent, err)
		}
	}()

	previous := requestObservation(req.Context()).collector.Snapshot()
	if previous.RateLimited || previous.LocalError != nil {
		err = previous.LocalError
		if previous.RateLimited {
			err = errors.Join(err, ErrObservationRateLimited)
		}
		if req.Body != nil {
			err = errors.Join(err, req.Body.Close())
		}
		return nil, err
	}
	p := PriorityFromContext(req.Context())
	if p > Auxiliary || req.URL == nil || req.URL.Scheme != "https" || req.URL.Host == "" {
		if req.Body != nil {
			err = errors.Join(ErrUnavailable, req.Body.Close())
		} else {
			err = ErrUnavailable
		}
		return nil, err
	}
	if t.base.Proxy != nil {
		proxy, proxyErr := t.base.Proxy(req)
		if proxyErr != nil || proxy != nil {
			err = errors.Join(ErrUnavailable, proxyErr)
			if req.Body != nil {
				err = errors.Join(err, req.Body.Close())
			}
			return nil, err
		}
	}
	lease, e := t.budget.Acquire(req.Context(), p)
	if e != nil || lease == nil {
		if req.Body != nil {
			e = errors.Join(e, req.Body.Close())
		}
		if e == nil {
			e = ErrUnavailable
		}
		return nil, e
	}
	var sequence uint64
	obs := t.budget.observation
	scope := requestObservation(req.Context())
	if obs != nil {
		var obsErr error
		if scope.kind == ObservationPoll && req.Method != http.MethodGet {
			obsErr = ErrUnavailable
		} else {
			sequence, obsErr = obs.Begin(req.Context(), lease, scope.kind, scope.key)
		}
		if obsErr == nil && scope.kind == ObservationPoll {
			var remaining time.Duration
			remaining, obsErr = obs.PollRemaining(req.Context(), scope.key)
			if obsErr == nil && remaining > 0 {
				obsErr = ErrObservationDeferred
			}
		}
		obsErr = errors.Join(obsErr, req.Context().Err())
		if obsErr != nil {
			scope.collector.record(false, obsErr)
			if req.Body != nil {
				obsErr = errors.Join(obsErr, req.Body.Close())
			}
			if sequence != 0 {
				settle, cancel := context.WithTimeout(context.WithoutCancel(req.Context()), 2*time.Second)
				finishErr := obs.Finish(settle, lease, sequence, ObservationNoResponse, nil)
				cancel()
				scope.collector.record(false, finishErr)
				if finishErr != nil {
					t.cleanupError(finishErr)
				}
				obsErr = errors.Join(obsErr, finishErr)
			}
			obsErr = errors.Join(obsErr, lease.Release())
			scope.collector.record(false, obsErr)
			return nil, obsErr
		}
	}
	gate := &connectionGate{ctx: req.Context(), firstWrite: t.firstWrite, inflight: t.inflight}
	tr := t.base.Clone()
	tr.Proxy = nil
	tr.DisableKeepAlives = true
	tr.ForceAttemptHTTP2 = false
	tr.TLSNextProto = map[string]func(string, *tls.Conn) http.RoundTripper{}
	tr.DialTLSContext = func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, _, e := net.SplitHostPort(addr)
		if e != nil {
			return nil, e
		}
		host = strings.Trim(host, "[]")
		cfg := tr.TLSClientConfig
		if cfg == nil {
			cfg = &tls.Config{}
		} else {
			cfg = cfg.Clone()
		}
		cfg.ServerName = host
		cfg.NextProtos = []string{"http/1.1"}
		dial := t.base.DialContext
		if dial == nil {
			dial = (&net.Dialer{KeepAlive: -1}).DialContext
		}
		raw, e := dial(ctx, network, addr)
		if e != nil {
			return nil, e
		}
		tc := tls.Client(raw, cfg)
		handshakeCtx := ctx
		cancel := func() {}
		if tr.TLSHandshakeTimeout > 0 {
			handshakeCtx, cancel = context.WithTimeout(ctx, tr.TLSHandshakeTimeout)
		}
		defer cancel()
		if e = tc.HandshakeContext(handshakeCtx); e != nil {
			raw.Close()
			return nil, e
		}
		if !gate.register(tc) {
			return nil, io.ErrClosedPipe
		}
		return &gatedConn{Conn: tc, gate: gate}, nil
	}
	resp, e = tr.RoundTrip(req)
	if resp == nil {
		if t.beforeStop != nil {
			t.beforeStop(gate)
		}
		stopErr := gate.stop()

		sent = gate.sent.Load()
		var finishErr error
		if obs != nil {
			settle, cancel := context.WithTimeout(context.WithoutCancel(req.Context()), 2*time.Second)
			finishErr = obs.Finish(settle, lease, sequence, ObservationNoResponse, nil)
			cancel()
			scope.collector.record(false, finishErr)
			if finishErr != nil {
				t.cleanupError(finishErr)
			}
		}
		cleanup := errors.Join(stopErr, finishErr, lease.Release())
		tr.CloseIdleConnections()
		return nil, errors.Join(e, cleanup)
	}
	sent = gate.sent.Load()
	if obs != nil {
		result := ObservationResponse
		var hint *time.Duration
		if resp.StatusCode == http.StatusTooManyRequests {
			result = ObservationRateLimited
			scope.collector.record(true, nil)
			if scope.kind == ObservationPoll {
				hint = retryAfterHint(resp.Header.Get("Retry-After"), t.budget.clk.Now())
			}
		}
		settle, cancel := context.WithTimeout(context.WithoutCancel(req.Context()), 2*time.Second)
		finishErr := obs.Finish(settle, lease, sequence, result, hint)
		cancel()
		if finishErr != nil {
			scope.collector.record(false, finishErr)
			t.cleanupError(finishErr)
		}
	}
	gate.mu.Lock()
	if resp.TLS == nil && gate.tlsState != nil {
		state := *gate.tlsState
		resp.TLS = &state
	}
	gate.mu.Unlock()
	owner := &responseOwner{body: resp.Body, done: make(chan struct{}), finish: func() error { e := errors.Join(gate.stop(), lease.Release()); tr.CloseIdleConnections(); return e }}
	resp.Body = owner
	go func() {
		select {
		case <-req.Context().Done():
			if e := owner.Close(); e != nil {
				t.cleanupError(e)
			}
		case <-owner.done:
		}
	}()
	return resp, e
}

internal/accountbudgetruntime/launch_con:
func ParseLaunchConfig(mode string, modeSet bool, manifest string, manifestSet bool) (Config, error) {
	if !modeSet && !manifestSet {
		return Config{Mode: ModeOff}, nil
	}
	switch {
	case modeSet && mode == "off" && !manifestSet:
		return Config{Mode: ModeOff}, nil
	case modeSet && mode == "required" && manifestSet && manifest != "":
		return Config{Mode: ModeRequired, Manifest: manifest}, nil
	default:
		return Config{}, fmt.Errorf("%w: invalid budget launch mode", accountbudget.ErrUnavailable)
	}
}

internal/accountbudgetruntime/offline_li:
func CheckOffline(ctx context.Context, path string) error {
	return checkOffline(ctx, path, clock.SystemBootSource().Snapshot)
}

func ProvisionOffline(ctx context.Context, root, path, scope, instance string) error {
	return provisionOffline(ctx, root, path, scope, instance, nil)
}

func checkOffline(ctx context.Context, path string, snapshot func() (clock.BootStamp, error)) error {
	f, err := Open(ctx, Config{Mode: ModeRequired, Manifest: path, CleanupError: func(error) {}})
	if err != nil {
		return err
	}
	if err = ctx.Err(); err == nil {
		_, err = snapshot()
	}
	if err == nil {
		err = ctx.Err()
	}
	return errors.Join(err, f.Close())
}

func provisionOffline(ctx context.Context, root, path, scope, instance string, fault offlineFault) (result error) {
	if ctx == nil {
		return accountbudget.ErrUnavailable
	}
	inject := func(stage string) error {
		if fault == nil {
			return nil
		}
		return fault(stage)
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	if !filepath.IsAbs(path) || filepath.Clean(path) != path || path == "/" {
		return errors.New("invalid manifest path")
	}
	rel, err := filepath.Rel(root, path)
	if err != nil || rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))) {
		return errors.New("manifest inside root")
	}
	rootFD, _, err := offlineDir(root)
	if err != nil {
		return err
	}
	defer func() { result = errors.Join(result, unix.Close(rootFD)) }()
	rootID, err := offlineID(rootFD)
	if err != nil {
		return err
	}
	var fs unix.Statfs_t
	if err = unix.Fstatfs(rootFD, &fs); err != nil {
		return err
	}
	if !supportedOfflineFS(int64(fs.Type)) {
		return errors.New("unsupported filesystem")
	}
	dup, err := unix.FcntlInt(uintptr(rootFD), unix.F_DUPFD_CLOEXEC, 0)
	if err != nil {
		return err
	}
	dir := os.NewFile(uintptr(dup), root)
	names, e := dir.Readdirnames(1)
	closeErr := dir.Close()
	if e != nil && !errors.Is(e, io.EOF) {
		return errors.Join(e, closeErr)
	}
	if closeErr != nil {
		return closeErr
	}
	if len(names) != 0 {
		return errors.New("root is not empty")
	}
	parent, ancestors, err := offlineDir(filepath.Dir(path))
	if err != nil {
		return err
	}
	defer func() { result = errors.Join(result, unix.Close(parent)) }()
	parentID, err := offlineID(parent)
	if err != nil {
		return err
	}
	ancestors = append(ancestors, parentID)
	for _, id := range ancestors {
		if id == rootID {
			return errors.New("manifest inside root")
		}
	}
	name := filepath.Base(path)
	var st unix.Stat_t
	e = unix.Fstatat(parent, name, &st, unix.AT_SYMLINK_NOFOLLOW)
	if e == nil {
		return errors.New("manifest already exists")
	}
	if !errors.Is(e, unix.ENOENT) {
		return e
	}
	if err = ctx.Err(); err != nil {
		return err
	}
	if err = accountbudget.Provision(root, scope, instance); err != nil {
		return err
	}
	if err = inject("after-provision"); err != nil {
		return err
	}
	if err = ctx.Err(); err != nil {
		return err
	}
	if err = offlineSameRoot(root, rootID); err != nil {
		return err
	}
	b, err := accountbudget.OpenContext(ctx, accountbudget.Config{Root: root, Scope: scope, Instance: instance, Clock: clock.System()})
	if err != nil {
		return err
	}
	event, err := accountbudget.ProvisionObservation(b)
	var queue, wire accountbudget.FileID
	if err == nil {
		queue, err = offlineFileID(rootFD, "queue.lock")
	}
	if err == nil {
		wire, err = offlineFileID(rootFD, "wire.lock")
	}
	ident := accountbudget.Identity{Root: rootID, Queue: queue, Wire: wire}
	if err == nil {
		err = b.VerifyIdentity(ident)
	}
	err = errors.Join(err, b.Close())
	if err != nil {
		return err
	}
	m := manifest{Version: 2, Root: root, Scope: scope, Instance: instance, Identity: ident, EventLock: event}
	data, err := json.Marshal(m)
	if err != nil {
		return err
	}
	var random [16]byte
	if _, err = rand.Read(random[:]); err != nil {
		return err
	}
	tmp := ".a166-" + hex.EncodeToString(random[:])
	fd, err := unix.Openat(parent, tmp, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0600)
	if err != nil {
		return err
	}
	file := os.NewFile(uintptr(fd), tmp)
	pending := true
	defer func() {
		if pending {
			if e := unix.Unlinkat(parent, tmp, 0); e != nil && !errors.Is(e, unix.ENOENT) {
				result = errors.Join(result, e)
			}
		}
	}()
	var fileStat unix.Stat_t
	if e = unix.Fstat(fd, &fileStat); e != nil || fileStat.Mode&unix.S_IFMT != unix.S_IFREG || fileStat.Mode&07777 != 0600 || fileStat.Uid != uint32(os.Geteuid()) || fileStat.Nlink != 1 {
		return errors.Join(errors.New("unsafe temporary manifest"), e, file.Close())
	}
	e = inject("write")
	if e == nil {
		var n int
		n, e = file.Write(data)
		if e == nil && n != len(data) {
			e = io.ErrShortWrite
		}
	}
	if e == nil {
		e = inject("file-sync")
	}
	if e == nil {
		e = file.Sync()
	}
	fileCloseErr := errors.Join(inject("close"), file.Close())
	e = errors.Join(e, fileCloseErr)
	if e != nil {
		return e
	}
	if e = ctx.Err(); e != nil {
		return e
	}
	if e = inject("before-final-root"); e != nil {
		return e
	}
	if e = offlineSameRoot(root, rootID); e != nil {
		return e
	}
	if e = inject("rename"); e != nil {
		return e
	}
	if e = unix.Renameat2(parent, tmp, parent, name, unix.RENAME_NOREPLACE); e != nil {
		return e
	}
	pending = false
	if e = inject("dir-sync"); e != nil {
		return e
	}
	if e = unix.Fsync(parent); e != nil {
		return e
	}
	return nil
}

