func NewContext(ctx context.Context, opts Options) (*Context, error) {
	path, err := NewOrderPath(opts)
	if err != nil {
		return nil, err
	}
	paths, cfg, tokenFile := path.Paths, path.Config, path.TokenFile
	off := path.official

	auditLog, err := openAuditLog(opts)
	if err != nil {
		return nil, err
	}
	clk := opts.Clock
	if clk == nil {
		clk = clock.System()
	}

	gate := cfg.Engine.AutomationGate
	status := newAutomationStatus(gate, paths, opts.protectionReadiness())

	publisher, notifications := resolveNotificationPublisher(cfg.Engine.Notifications, opts.Getenv)
	if opts.Publisher != nil {
		publisher = opts.Publisher
	}

	if err := recordGateSettings(auditLog, gate, cfg.Engine.Adoption, notifications,
		status.AttestationFile, cfg.Engine.ExitSourceAgeReport); err != nil {

		return nil, fmt.Errorf("engine: recording the automation-gate audit trail: %w", err)
	}

	accountRef, err := resolveAccountRef(ctx, off)
	if err != nil {
		return nil, refuseStartup(auditLog, gate, fmt.Errorf("%w: %w", ErrAccountUnresolved, err))
	}
	status.AccountRef = accountRef

	jrn, err := openEngineJournal(ctx, opts, clk)
	if err != nil {
		return nil, refuseStartup(auditLog, gate, err)
	}

	if err := bindApplyHooks(jrn, tradeOutcomeRefusalSink(opts.Logger)); err != nil {
		_ = jrn.Close()
		return nil, refuseStartup(auditLog, gate, err)
	}

	var borrowed *accountbudget.Budget
	if opts.BudgetFactory != nil {
		borrowed, err = opts.BudgetFactory.Budget()
		if err != nil {
			_ = jrn.Close()
			return nil, refuseStartup(auditLog, gate, err)
		}
	}
	wiring, err := buildGateway(ctx, gatewayInputs{
		journal:     jrn,
		trading:     path.Trading,
		official:    off,
		budget:      borrowed,
		accountRef:  accountRef,
		clock:       clk,
		configDir:   paths.ConfigDir,
		manifestPin: protectionManifestPin(opts),
		logger:      opts.Logger,
		publisher:   publisher,

		protectionOverride: opts.protectionOverride,
	})
	if err != nil {
		_ = jrn.Close()
		return nil, refuseStartup(auditLog, gate, err)
	}

	guardian := opts.Guardian
	if gate.Enabled && guardian == nil && !opts.disableProductionGuardian {
		factory := opts.productionGuardianFactory
		if factory == nil {
			factory = defaultProductionGuardianFactory
		}
		guardian, err = factory(
			gate, jrn, clk, accountRef, wiring.notifier,
		)
		if err != nil {
			_ = jrn.Close()
			return nil, refuseStartup(auditLog, gate,
				fmt.Errorf("%w: %w", ErrAutomationGateRefused, err))
		}
	}

	automation, err := runInterlock(status, gate, auditLog, opts.Logger, gateFacts{
		guardian:  guardian,
		trading:   cfg.Trading,
		gateway:   wiring.gateway,
		transport: path.broker,
		now:       clk.Now(),
	})
	if err != nil {
		_ = jrn.Close()
		return nil, err
	}
	if !automation.Verified {
		guardian = nil
	}

	projection, err := strategyprojection.NewStore(strategyprojection.DormantSnapshot(clk.Now().UTC()))
	if err != nil {
		_ = jrn.Close()
		return nil, fmt.Errorf("engine: initialize strategy runtime projection: %w", err)
	}
	return &Context{
		Paths:                 paths,
		Config:                cfg,
		TokenFile:             tokenFile,
		Official:              off,
		AccountRef:            accountRef,
		Journal:               jrn,
		Gateway:               wiring.gateway,
		Entry:                 wiring.entry,
		Resolver:              wiring.resolver,
		Reconcile:             wiring.reconcile,
		Retrier:               wiring.retrier,
		Notifier:              wiring.notifier,
		Ingest:                wiring.ingest,
		Converge:              wiring.converge,
		Names:                 wiring.names,
		exitFloor:             wiring.floor,
		exitLowerLimits:       newExitLowerLimitBoard(clk, off, jrn, jrn, accountRef, nil),
		Automation:            automation,
		Guardian:              guardian,
		Audit:                 auditLog,
		Log:                   opts.Logger,
		clk:                   clk,
		official:              off,
		broker:                path.broker,
		conditional:           path.conditional,
		tradingService:        path.Trading,
		strategyDispatchOwner: &strategyDispatchOwnerCoordinator{},
		strategyProjection:    projection,
	}, nil
}

