func (r *Retrier) Query(ctx context.Context, kind RequiredQuery, fn func(context.Context) error) error {
	ctx, collector, err := r.pollContext(ctx, kind)
	if err != nil {
		return err
	}
	policy := r.Policy
	if policy.MaxAttempts <= 0 {
		policy = DefaultRetryPolicy()
	}
	clk := r.Clock
	if clk == nil {
		clk = clock.System()
	}
	deadline := clk.Now().Add(policy.Budget)

	var lastErr error
	for attempt := 1; attempt <= policy.MaxAttempts; attempt++ {
		err := fn(ctx)
		lastErr = err
		class := ClassifyQueryError(err)
		if collector != nil && class == ClassAuthFatal {
			if r.Gate != nil {
				r.Gate.Block(ReasonBrokerAuthRejected, fmt.Sprintf("%s was refused by the broker: %v", kind, err))
			}
			return errors.Join(err, r.escalateCredentialFailure(ctx), pollError(collector, err))
		}
		if observedErr := pollError(collector, err); observedErr != nil {
			return observedErr
		}
		switch class {
		case ClassOK:
			if r.Gate != nil {
				r.Gate.RecordSuccess(kind)
			}
			return nil

		case ClassAuthFatal:

			if r.Gate != nil {
				r.Gate.Block(ReasonBrokerAuthRejected,
					fmt.Sprintf("%s was refused by the broker: %v", kind, err))
			}
			return errors.Join(err, r.escalateCredentialFailure(ctx))

		case ClassPermanent, ClassCanceled:
			return err

		case ClassRateLimited:
			wait, ok := r.rateLimitWait(policy, attempt)
			if !ok {
				return fmt.Errorf("%w (Retry-After beyond the %s cap)", err, policy.MaxRetryAfter)
			}
			if !r.sleepWithin(ctx, clk, wait, deadline) {
				return err
			}

		default:
			if attempt == policy.MaxAttempts {
				return err
			}
			if !r.sleepWithin(ctx, clk, policy.BackoffFor(attempt, policy.BaseBackoff), deadline) {
				return err
			}
		}
	}
	return lastErr
}

