func runWithOptions(market, date, configDir, ledgerPath, out string, gap time.Duration, maxSymbols int, dryRun, types bool, opts ...official.Option) (result error) {
	day, err := time.Parse("2006-01-02", date)
	if err != nil {
		return fmt.Errorf("--date: %w", err)
	}
	plans, err := planFor(market, day)
	if err != nil {
		return err
	}
	f, err := os.Open(ledgerPath)
	if err != nil {
		return err
	}
	symbols, digest, err := listSymbols(f, market, date)
	f.Close()
	if err != nil {
		return err
	}
	if maxSymbols > 0 && len(symbols) > maxSymbols {
		symbols = symbols[:maxSymbols]
	}
	if len(symbols) == 0 {
		return fmt.Errorf("no %s 10:00-round J2 judgments on %s in the ledger; nothing to fetch", market, date)
	}
	if dryRun {
		view := map[string]any{"market": market, "date": date, "symbols": symbols, "calls": len(symbols) * len(plans), "plans": plans,
			"types_calls": (len(symbols) + stocksBatchMax - 1) / stocksBatchMax}
		body, _ := json.MarshalIndent(view, "", "  ")
		fmt.Println(string(body))
		return nil
	}
	if configDir == "" {
		return errors.New("--config-dir is required (the default token cache would invalidate the engine's token)")
	}
	credentialFile, tokenFile, err := apppaths.OpenAPI(configDir)
	if err != nil {
		return fmt.Errorf("resolving the Open API paths: %w", err)
	}
	credentials, err := official.LoadCredentials(os.Getenv, credentialFile)
	if err != nil {
		return fmt.Errorf("reading the Open API credentials: %w", err)
	}
	if credentials == nil {
		return errors.New("no Open API credentials; run `tossctl openapi login` first")
	}
	ctx, cancel := context.WithTimeout(context.Background(), runBudget)
	defer cancel()
	mode, modeSet := os.LookupEnv("TOSSOS_ACCOUNT_BUDGET_MODE")
	manifest, manifestSet := os.LookupEnv("TOSSOS_ACCOUNT_BUDGET_MANIFEST")
	cfg, err := accountbudgetruntime.ParseLaunchConfig(mode, modeSet, manifest, manifestSet)
	if err != nil {
		return err
	}
	cfg.CleanupError = func(error) { fmt.Fprintln(os.Stderr, "budget cleanup failed") }
	factory, err := accountbudgetruntime.Open(ctx, cfg)
	if err != nil {
		return err
	}
	defer func() { result = errors.Join(result, factory.Close()) }()
	client, err := factory.NewClient(*credentials, tokenFile, opts...)
	if err != nil {
		return err
	}
	ctx = accountbudget.WithPriority(ctx, accountbudget.Auxiliary)
	if types {
		path := filepath.Join(out, "security-types.json")
		tr, err := updateTypes(ctx, client, path, market, date, symbols, time.Now)
		if err != nil {
			return err
		}
		fmt.Printf("updated %s: listed %d, queried %d, calls %d, unclassified %d %v\n",
			path, len(symbols), len(tr.Queried), tr.Calls, len(tr.Unclassified), tr.Unclassified)
		return nil
	}
	rc, err := collect(ctx, client, market, date, symbols, plans, gap, sleepCtx, time.Now)
	if err != nil {
		return err
	}
	rc.Prereg, rc.LedgerDigest = preregDoc, digest
	rc.ListRule = "J2 judgments with session date " + date + " and local time 10:00:00 <= at < 10:10:00"
	path, err := writeReceipt(out, rc)
	if err != nil {
		return err
	}
	fmt.Printf("wrote %s: symbols %d, calls %d, elapsed %.1fs, symbols with bars %d\n",
		path, len(rc.Symbols), rc.Calls, rc.ElapsedSeconds, len(rc.Bars))
	return nil
}

